const h = this.helpers;
async function probe(url, timeout) {
  const t0 = Date.now();
  try {
    const r = await h.httpRequest({method: 'GET', url, returnFullResponse: true, ignoreHttpStatusErrors: true, json: true, timeout});
    return {url, ok: true, status: r.statusCode, responseKeys: Object.keys(r), headerKeys: Object.keys(r.headers || {}).slice(0, 6), bodyType: typeof r.body, ms: Date.now() - t0};
  } catch (e) {
    return {url, ok: false, error: String(e.message).slice(0, 200), code: e.code || (e.cause && e.cause.code) || null, ms: Date.now() - t0};
  }
}
