// MCP over Streamable HTTP from a Code node: initialize, initialized, tools/list,
// two tools/call on one session, then DELETE. Records the session header and reply format.
const h = this.helpers;
const url = 'http://host.docker.internal:3000/mcp';
async function send(method, body, sid) {
  const headers = {'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream'};
  if (sid) headers['mcp-session-id'] = sid;
  const r = await h.httpRequest({method, url, headers, body: body ? JSON.stringify(body) : undefined,
    returnFullResponse: true, ignoreHttpStatusErrors: true, json: false, timeout: 20000});
  const hdrs = r.headers || {};
  const ct = String(hdrs['content-type'] || '');
  const text = r.body == null ? '' : (typeof r.body === 'string' ? r.body : JSON.stringify(r.body));
  let msg = null;
  if (ct.includes('text/event-stream')) {
    for (const l of text.split('\n')) {
      if (!l.startsWith('data:')) continue;
      try { const m = JSON.parse(l.slice(5).trim()); if (body && m.id === body.id) msg = m; } catch (e) {}
    }
  } else if (text) { try { msg = JSON.parse(text); } catch (e) {} }
  return {status: r.statusCode, contentType: ct, headers: hdrs, msg, head: text.slice(0, 200)};
}
const steps = {};
const init = await send('POST', {jsonrpc: '2.0', id: 1, method: 'initialize',
  params: {protocolVersion: '2025-06-18', capabilities: {}, clientInfo: {name: 'n8n-spike', version: '0'}}});
const sidHeader = Object.keys(init.headers).find(k => k.toLowerCase() === 'mcp-session-id') || null;
const sid = sidHeader ? init.headers[sidHeader] : null;
steps.initialize = {status: init.status, contentType: init.contentType, sessionHeader: sidHeader, sessionIdLength: sid ? String(sid).length : 0,
  protocolVersion: init.msg && init.msg.result && init.msg.result.protocolVersion, serverInfo: init.msg && init.msg.result && init.msg.result.serverInfo};
const note = await send('POST', {jsonrpc: '2.0', method: 'notifications/initialized'}, sid);
steps.initialized = {status: note.status, contentType: note.contentType};
const list = await send('POST', {jsonrpc: '2.0', id: 2, method: 'tools/list', params: {}}, sid);
steps.toolsList = {status: list.status, contentType: list.contentType,
  tools: ((list.msg && list.msg.result && list.msg.result.tools) || []).map(t => t.name)};
const c1 = await send('POST', {jsonrpc: '2.0', id: 3, method: 'tools/call', params: {name: 'list_loki_label_names', arguments: {datasourceUid: 'loki'}}}, sid);
steps.call1 = {status: c1.status, contentType: c1.contentType, isError: !!(c1.msg && c1.msg.result && c1.msg.result.isError),
  rpcError: c1.msg && c1.msg.error ? c1.msg.error.message : null,
  text: c1.msg && c1.msg.result && c1.msg.result.content ? String(c1.msg.result.content.map(x => x.text).join('')).slice(0, 200) : c1.head};
const c2 = await send('POST', {jsonrpc: '2.0', id: 4, method: 'tools/call', params: {name: 'query_prometheus',
  arguments: {datasourceUid: 'PBFA97CFB590B2093', expr: 'sum(up{namespace="taskboard"})', queryType: 'instant'}}}, sid);
steps.call2 = {status: c2.status, contentType: c2.contentType, isError: !!(c2.msg && c2.msg.result && c2.msg.result.isError),
  rpcError: c2.msg && c2.msg.error ? c2.msg.error.message : null,
  text: c2.msg && c2.msg.result && c2.msg.result.content ? String(c2.msg.result.content.map(x => x.text).join('')).slice(0, 200) : c2.head};
const del = await send('DELETE', null, sid);
steps.delete = {status: del.status, head: del.head};
const after = await send('POST', {jsonrpc: '2.0', id: 5, method: 'tools/list', params: {}}, sid);
steps.afterDelete = {status: after.status, head: after.head};
return [{json: steps}];
